const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Stack Overflow Survey Analysis";
pres.title = "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey";

// Color palette - Professional Navy/Teal for analytical, data-forward tone
const C = {
  navy: "1B2A4A",
  darkSlate: "0F172A",
  lightBg: "F8F9FB",
  cardBg: "FFFFFF",
  accent: "2E86AB",
  accentLight: "3A9BC8",
  orange: "E8630A",
  teal: "0D9488",
  textDark: "1E293B",
  textMuted: "64748B",
  textLight: "F1F5F9",
  border: "E2E8F0",
  greenMuted: "059669",
  redMuted: "DC2626",
};

const HEADER_FONT = "Georgia";
const BODY_FONT = "Calibri";

// Fresh shadow factory (never reuse shadow objects)
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1
});

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
const slide1 = pres.addSlide();
slide1.background = { color: C.navy };

// Accent bar at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 0.6, w: 1.5, h: 0.06, fill: { color: C.accent }
});

// Title
slide1.addText([
  { text: "Developer Workforce &", options: { breakLine: true } },
  { text: "Compensation Trends" }
], {
  x: 0.5, y: 0.9, w: 9, h: 1.6,
  fontSize: 40, fontFace: HEADER_FONT, color: "FFFFFF", bold: true,
  margin: 0
});

// Subtitle line
slide1.addText("2024 Stack Overflow Survey", {
  x: 0.5, y: 2.6, w: 9, h: 0.5,
  fontSize: 22, fontFace: BODY_FONT, color: C.accent,
  margin: 0
});

// Stat card 1 - respondents
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.5, w: 3.8, h: 0.9,
  fill: { color: C.darkSlate }
});
slide1.addText("65,437", {
  x: 0.7, y: 3.5, w: 3.4, h: 0.55,
  fontSize: 32, fontFace: HEADER_FONT, color: C.accent, bold: true,
  margin: 0
});
slide1.addText("respondents across 180+ countries", {
  x: 0.7, y: 4.0, w: 3.4, h: 0.35,
  fontSize: 12, fontFace: BODY_FONT, color: C.textMuted,
  margin: 0
});

// Stat card 2 - salary responses
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 4.6, y: 3.5, w: 3.0, h: 0.9,
  fill: { color: C.darkSlate }
});
slide1.addText("22,677", {
  x: 4.8, y: 3.5, w: 2.6, h: 0.55,
  fontSize: 32, fontFace: HEADER_FONT, color: C.orange, bold: true,
  margin: 0
});
slide1.addText("salary responses (34.7% rate)", {
  x: 4.8, y: 4.0, w: 2.6, h: 0.35,
  fontSize: 12, fontFace: BODY_FONT, color: C.textMuted,
  margin: 0
});

// Source
slide1.addText("Source: survey.stackoverflow.co/2024/work", {
  x: 0.5, y: 5.1, w: 9, h: 0.25,
  fontSize: 10, fontFace: BODY_FONT, color: C.textMuted,
  margin: 0
});

// ============================================================
// SLIDE 2: Employment Status
// ============================================================
const slide2 = pres.addSlide();
slide2.background = { color: C.lightBg };

// Title
slide2.addText("84% of Developers Are Working, but\nFull-Time Employment Dips in the U.S.", {
  x: 0.5, y: 0.3, w: 9, h: 0.85,
  fontSize: 24, fontFace: HEADER_FONT, color: C.textDark, bold: true,
  margin: 0
});

// Global employment breakdown bar chart
const employmentData = [{
  name: "Global Share (%)",
  labels: ["Full-time", "Freelance/\nContractor", "Full-time\nStudent"],
  values: [69, 16.4, 13.2]
}];

slide2.addChart(pres.charts.BAR, employmentData, {
  x: 0.5, y: 1.3, w: 5.2, h: 3.3,
  barDir: "col",
  chartColors: [C.accent],
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 11,
  catAxisLabelColor: C.textDark,
  catAxisLabelFontSize: 10,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showLegend: false,
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valAxisMinVal: 0,
  valAxisMaxVal: 80,
  valAxisNumFmt: '0"%"'
});

// Callout card 1: U.S. full-time drop
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 6.0, y: 1.3, w: 3.5, h: 1.2,
  fill: { color: C.cardBg },
  shadow: makeShadow()
