  x: 6.0, y: 4.0, w: 3.5, h: 1.0,
  fill: { color: C.cardBg },
  shadow: makeShadow()
});
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 6.0, y: 4.0, w: 0.06, h: 1.0,
  fill: { color: C.teal }
});
slide2.addText("Regional Split", {
  x: 6.25, y: 4.05, w: 3.1, h: 0.35,
  fontSize: 16, fontFace: HEADER_FONT, color: C.teal, bold: true,
  margin: 0
});
slide2.addText("U.K./Ukraine lean freelance;\nGermany/India lean student", {
  x: 6.25, y: 4.4, w: 3.1, h: 0.55,
  fontSize: 11, fontFace: BODY_FONT, color: C.textMuted,
  margin: 0
});

// Footer bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.35, w: 10, h: 0.275,
  fill: { color: C.navy }
});
slide2.addText("Source: Stack Overflow Survey 2024", {
  x: 0.5, y: 5.35, w: 9, h: 0.275,
  fontSize: 8, fontFace: BODY_FONT, color: C.textLight,
  valign: "middle", margin: 0
});

// ============================================================
// SLIDE 3: Work Environment Shift
// ============================================================
const slide3 = pres.addSlide();
slide3.background = { color: C.lightBg };

slide3.addText("In-Person Work Rises to 20% While\nHybrid Holds Steady at 42%", {
  x: 0.5, y: 0.3, w: 9, h: 0.85,
  fontSize: 24, fontFace: HEADER_FONT, color: C.textDark, bold: true,
  margin: 0
});

// Grouped bar chart: 3-year trend
const workEnvData = [
  { name: "2022", labels: ["Remote", "Hybrid", "In-Person"], values: [46, 39, 15] },
  { name: "2023", labels: ["Remote", "Hybrid", "In-Person"], values: [41, 42, 16] },
  { name: "2024", labels: ["Remote", "Hybrid", "In-Person"], values: [38, 42, 20] }
];

slide3.addChart(pres.charts.BAR, workEnvData, {
  x: 0.5, y: 1.3, w: 5.5, h: 3.4,
  barDir: "col",
  barGrouping: "clustered",
  chartColors: [C.accent, C.teal, C.orange],
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 9,
  catAxisLabelColor: C.textDark,
  catAxisLabelFontSize: 11,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: C.border, size: 0.5 },
  catGridLine: { style: "none" },
  showLegend: true,
  legendPos: "t",
  legendColor: C.textDark,
  legendFontSize: 10,
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  valAxisMinVal: 0,
  valAxisMaxVal: 55,
  valAxisNumFmt: '0"%"'
});

// Trend cards on right
// Card 1: In-person rise
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.3, w: 3.2, h: 1.1,
