slide3.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.3, w: 0.06, h: 1.1,
  fill: { color: C.orange }
});
slide3.addText("+5 pp", {
  x: 6.55, y: 1.35, w: 2.8, h: 0.5,
